/**
 * Venue anchors in scene metres (x = east, z = south; origin = DE Exchange Hotel).
 * Generated by scripts/build-map.py from the Google Maps coordinates you supplied:
 *   DE Exchange Hotel & Apartment  4.6467952, 7.9429389
 *   Royalty Hotels & Recreations   4.6450000, 7.9358333
 *   Blade Lounge                   4.6428571, 7.9168536
 *   Amalgamation House, Ikot Abasi 4.5698104, 7.5468473  (44.8 km away; placed 8.6 km out on its true bearing)
 * `yaw` turns a model's front (+Z) to face its nearest street.
 */
export type VenueKey = "deExchange" | "royalty" | "blade" | "amalgamation";

export const IKOT_OFFSET: [number, number] = [-8443.1, 1635.4];
export const IKOT_TRUE_KM = 44.8;

export const VENUES: Record<VenueKey, { x: number; z: number; yaw: number; name: string; town: string; mapUrl: string }> = {
  deExchange: {
    x: 0,
    z: 0,
    yaw: 0.3248,
    name: "DE Exchange Hall",
    town: "DE Exchange Hotel & Apartment, Eket",
    mapUrl: "https://www.google.com/maps/place/DE+EXCHANGE+HOTEL+AND+APARTMENT/@4.6467828,7.9428942,21z",
  },
  royalty: {
    x: -788.4,
    z: 198.5,
    yaw: -3.0433,
    name: "Royalty Hotels",
    town: "Royalty Hotels & Recreations, Eket",
    mapUrl: "https://www.google.com/maps/place/Royalty+Hotels+%26+Recreations+Eket/@4.6451357,7.9358161,21z",
  },
  blade: {
    x: -2894.3,
    z: 435.5,
    yaw: 0.5343,
    name: "Blade Lounge",
    town: "Blade Lounge, Eket",
    mapUrl: "https://www.google.com/maps/place/Blade+Lounge/@4.642859,7.9159432,18z",
  },
  amalgamation: {
    x: IKOT_OFFSET[0],
    z: IKOT_OFFSET[1],
    yaw: -0.5815,
    name: "Amalgamation House",
    town: "Amalgamation House, Ikot Abasi",
    mapUrl: "https://www.google.com/maps/place/Amalgamation+House/@4.5698157,7.5442724,17z",
  },
};

/** Venue-local (x right, y up, z towards the street) → scene coordinates. */
export function toScene(key: VenueKey, [lx, ly, lz]: [number, number, number]): [number, number, number] {
  const v = VENUES[key];
  const c = Math.cos(v.yaw);
  const s = Math.sin(v.yaw);
  return [v.x + lx * c + lz * s, ly, v.z - lx * s + lz * c];
}
